a:acp.a:expr:
= a!map( folio: pv!request.folio, process: pv!request.idProceso, subprocess: pv!request.idSubproceso, movementType: if( or( pv!flagMarcaSubSecuenteINFONAVIT = true, pv!flagMarcaSubsecuenteFOVISSSTE = true ), "CARGO", "ABONO" ), dateShare: if( a!isNotNullOrEmpty(pv!fechaRecalculo), text(pv!fechaRecalculo, "yyyyMMdd"), "" ), folioRel: if( tointeger(pv!estatusMovValor) = 3, "na", if( or( pv!flagMarcaSubSecuenteINFONAVIT = true, pv!flagMarcaSubsecuenteFOVISSSTE = true ), pv!request.folioSubSecuente, "na" ),
), snapshot: pv!request.idSnapshot, reprocessFlag: pv!estatusMovValor, parameters: { liquidationDate: if( a!isNotNullOrEmpty(pv!fechaRecalculo), text(pv!fechaRecalculo, "yyyyMMdd"), "" ), substage: pv!request.idSubetapa, movementStatus: "na", fileSource: "na", filename: "", fileOrigin: "na", fileSourceDate: "na", user: "APPIAN", processInstance: pv!request.idInstancia, stage: pv!request.idEtapa,
} )

output-exprs.el:
requestRT:#"_a-0000ee6c-cc70-8000-9bb5-011c48011c48_355496"(
  folio:pv!folio,
  nombre: pv!integrationName,
  instancia: pp!id,
  data: a!map(
    data:{
      a!map(
        request: pv!requestIntegration,
        response: pv!response,
        responseError: pv!errorService
      )
    }
  )
)

